"""Narrow synthetic Android API doubles for the actual icon activity host test.

These doubles model only the APIs used by IconPackActivity and the declared fake
launcher metadata. Framework callback delivery is simulated. They do not qualify
Android rotation, fold behavior, real package visibility or phone installation.
"""

import json
from pathlib import Path
import xml.etree.ElementTree as ET


# No real package inventory is queried. The report oracle is literal Java text
# independent of the activity formatter, including duplicate/foreign entries.
